/*
     * Logon to access a protected resource using DIGEST authentication, which will establish an SSO session.
     * Immediately try to access a protected resource in the NonLogin webapp while sending the SSO session cookie
     * provided by the first webapp. This should be successful with SC_OK 200 status.
     */
@Test
public void testDigestLoginAcceptProtectedWithCookies() throws Exception {
