/*
     * Logon to access a protected resource using DIGEST authentication, which will establish an SSO session.
     * Immediately try to access a protected resource in the NonLogin webapp while sending the SSO session cookie
     * provided by the first webapp. This should be successful with SC_OK 200 status.
     *
     * Then, wait long enough for the DIGEST session to expire. (The SSO session should remain active because the
     * NonLogin session has not yet expired).
     *
     * Try to access the protected resource again, before the SSO session has expired. This should be successful with
     * SC_OK 200 status.
     *
     * Finally, wait for the non-login session to expire and try again.. This should be rejected with SC_FORBIDDEN 403
     * status.
     *
     * (see bugfix https://bz.apache.org/bugzilla/show_bug.cgi?id=52303)
     */
@Test
public void testDigestExpiredAcceptProtectedWithCookies() throws Exception {
    doTestDigest(USER, PWD, CONTEXT_PATH_DIGEST + URI_PROTECTED, true, 401, true, true, NC1, CNONCE, QOP, true);
    doTestNonLogin(CONTEXT_PATH_NOLOGIN + URI_PROTECTED, true, false, 200);
    // wait long enough for the BASIC session to expire,
    // but not long enough for NonLogin session expiry
    Thread.sleep(SHORT_TIMEOUT_DELAY_MSECS);
    doTestNonLogin(CONTEXT_PATH_NOLOGIN + URI_PROTECTED, true, false, 200);
    // wait long enough for my NonLogin session to expire
    // and tear down the SSO session at the same time.
    Thread.sleep(LONG_TIMEOUT_DELAY_MSECS);
    doTestNonLogin(CONTEXT_PATH_NOLOGIN + URI_PROTECTED, false, true, 403);
}

@Test
public void testTimeoutGets408() throws IOException, LifecycleException {
    // Setup Tomcat instance
    Tomcat tomcat = getTomcatInstance();
    // No file system docBase required
    Context ctx = getProgrammaticRootContext();
    ((StandardHost) tomcat.getHost()).setErrorReportValveClass(null);
    Tomcat.addServlet(ctx, "TestServlet", new SyncServlet());
    ctx.addServletMappingDecoded("/*", "TestServlet");
    tomcat.start();
    try (Socket socket = new Socket("localhost", getPort())) {
        String request = "GET /async HTTP/1.1\r\nHost: localhost\r\ncontent-length: 101\r\n\r\n";
        OutputStream os = socket.getOutputStream();
        os.write(request.getBytes(StandardCharsets.UTF_8));
        InputStream is = socket.getInputStream();
        BufferedReader reader = new BufferedReader(new InputStreamReader(is, StandardCharsets.UTF_8));
        String opening = null;
        try {
            opening = reader.readLine();
        } catch (SocketException e) {
            // Handled below. An exception here means opening will be null
        }
        if (tomcat.getConnector().getProtocolHandlerClassName().contains("Nio2")) {
            Assert.assertNull("NIO2 unexpectedly returned a response", opening);
        } else {
            Assert.assertNotNull("Didn't get back a response", opening);
            StringBuilder sb = new StringBuilder(opening);
            try {
                Assert.assertTrue("expected status code " + HttpServletResponse.SC_REQUEST_TIMEOUT + " but got " + opening, opening.startsWith("HTTP/1.1 " + HttpServletResponse.SC_REQUEST_TIMEOUT));
                boolean connectionClose = false;
                while (reader.ready()) {
                    String line = reader.readLine();
                    if (line == null) {
                        break;
                    }
                    sb.append("\n").append(line);
                    if ("connection: close".equalsIgnoreCase(line)) {
                        connectionClose = true;
                    }
                    Assert.assertFalse(line.contains("Exception Report"));
                    Assert.assertFalse(line.contains("Status Report"));
                }
                Assert.assertTrue("No 'Connection: close' header seen", connectionClose);
            } catch (Throwable t) {
                Assert.fail("Response:\n" + sb);
                t.printStackTrace();
            }
        }
    }
}

