    client.doRequest(-1, false);
    Assert.assertTrue(client.isResponse200());
    Assert.assertTrue(client.isResponseBodyOK());
    client.reset();
    // 0 bytes - too small should fail
    client.doRequest(0, false);
    Assert.assertTrue(client.isResponse413());
    client.reset();
    // 1 byte - too small should fail
    client.doRequest(1, false);
    Assert.assertTrue(client.isResponse413());
    // Edge cases around actual content length
    client.reset();
    // Too small should fail
    client.doRequest(6, false);
    Assert.assertTrue(client.isResponse413());
    client.reset();
    // Just enough should pass
    client.doRequest(7, false);
    Assert.assertTrue(client.isResponse200());
    Assert.assertTrue(client.isResponseBodyOK());
    client.reset();
    // 1 extra - should pass
    client.doRequest(8, false);
    Assert.assertTrue(client.isResponse200());
    Assert.assertTrue(client.isResponseBodyOK());
    // Much larger
    client.reset();
    // Plenty of space - should pass
    client.doRequest(8096, false);
    Assert.assertTrue(client.isResponse200());
    Assert.assertTrue(client.isResponseBodyOK());
    // Check for case insensitivity
    client.reset();
    // Plenty of space - should pass
    client.doRequest(8096, true);
    Assert.assertTrue(client.isResponse200());
    Assert.assertTrue(client.isResponseBodyOK());
}

