@Test
public void testToAbsolutePerformance() throws Exception {
    Request req = new TesterRequest();
    Response resp = new Response(null);
    resp.setRequest(req);
    // Warm up
    doHomebrew(resp);
    doUri();
    // Note: With Java 11 the 'homebrew' approach is consistently 3-4 times faster on both MacOS (Intel) and Linux
    // With Java 22 EA the 'homebrew' approach is consistently a little over 2x faster on MacOS (M1)
    // To allow for timing differences between runs, a "best of n" approach
    // is taken for this test
    final int bestOf = 5;
    final int winTarget = (bestOf + 1) / 2;
    int homebrewWin = 0;
    int count = 0;
    while (count < bestOf && homebrewWin < winTarget) {
        long homebrew = doHomebrew(resp);
        long uri = doUri();
        log.info("Current 'home-brew': " + homebrew + "ms, Using URI: " + uri + "ms");
        if (homebrew < uri) {
            homebrewWin++;
        }
        count++;
    }
    Assert.assertTrue(homebrewWin == winTarget);
}

@Test
public void testSendFile() throws Exception {
    Tomcat tomcat = getTomcatInstance();
    Context root = tomcat.addContext("", TEMP_DIR);
    File[] files = new File[ITERATIONS];
    for (int i = 0; i < ITERATIONS; i++) {
        files[i] = generateFile(TEMP_DIR, "-" + i, EXPECTED_CONTENT_LENGTH * (i + 1));
        addDeleteOnTearDown(files[i]);
    }
    for (int i = 0; i < ITERATIONS; i++) {
        WritingServlet servlet = new WritingServlet(files[i]);
        Tomcat.addServlet(root, "servlet" + i, servlet);
        root.addServletMappingDecoded("/servlet" + i, "servlet" + i);
    }
    tomcat.start();
    ByteChunk bc = new ByteChunk();
    Map<String, List<String>> respHeaders = new HashMap<>();
    for (int i = 0; i < ITERATIONS; i++) {
        long start = System.currentTimeMillis();
        int rc = getUrl("http://localhost:" + getPort() + "/servlet" + i, bc, null, respHeaders);
        Assert.assertEquals(HttpServletResponse.SC_OK, rc);
        System.out.println("Client received " + bc.getLength() + " bytes in " + (System.currentTimeMillis() - start) + " ms.");
        Assert.assertEquals("Expected [" + EXPECTED_CONTENT_LENGTH * (i + 1L) + "], was [" + bc.getLength() + "]", EXPECTED_CONTENT_LENGTH * (i + 1L), bc.getLength());
        bc.recycle();
    }
}

