    ctx.addServletMappingDecoded("/*", "bug63816Servlet");
    tomcat.start();
    Client client = new Client();
    client.setPort(getPort());
    // @formatter:off
    client.setRequest(new String[] { "GET / HTTP/1.1" + CRLF + "Host: localhost:" + CRLF + CRLF });
    // @formatter:on
    client.connect();
    client.sendRequest();
    // Wait for Servlet to start processing request
    servletStartLatch.await();
    if (asyncEnd.isError()) {
        client.disconnect();
        clientDisconnectLatch.countDown();
        try {
            endLatch.await();
        } catch (InterruptedException e) {
            // Ignore
        }
    } else {
        client.setUseContentLength(true);
        client.readResponse(true);
    }
    Assert.assertFalse(failed.get());
}

