    // Make casual multipart request to "regular" servlet w/config
    // We expect that the server /will/ parse the parts, even though
    // there is no @MultipartConfig
    // send multipart request
    client.doRequest("/regular", true, true);
    Assert.assertEquals("Incorrect response for configured casual multipart request", "parts=1", client.getResponseBody());
    client.reset();
}

