@Test
public void testNoNonceBuilders() {
    Assert.assertEquals(CsrfPreventionFilter.PrefixPredicate.class, CsrfPreventionFilter.createNoNoncePredicate(null, "/images/*").getClass());
    Assert.assertEquals(CsrfPreventionFilter.SuffixPredicate.class, CsrfPreventionFilter.createNoNoncePredicate(null, "*.png").getClass());
    Assert.assertEquals(CsrfPreventionFilter.PatternPredicate.class, CsrfPreventionFilter.createNoNoncePredicate(null, "/^(/images/.*|.*\\.png)$/").getClass());
    Collection<Predicate<String>> chain = CsrfPreventionFilter.createNoNoncePredicates(null, "*.png,/js/*,*.jpg,/images/*,mime:*/png,mime:image/*");
    Assert.assertEquals(6, chain.size());
    Iterator<Predicate<String>> items = chain.iterator();
    Assert.assertEquals(CsrfPreventionFilter.SuffixPredicate.class, items.next().getClass());
    Assert.assertEquals(CsrfPreventionFilter.PrefixPredicate.class, items.next().getClass());
    Assert.assertEquals(CsrfPreventionFilter.SuffixPredicate.class, items.next().getClass());
    Assert.assertEquals(CsrfPreventionFilter.PrefixPredicate.class, items.next().getClass());
    Predicate<String> item = items.next();
    Assert.assertEquals(CsrfPreventionFilter.MimePredicate.class, item.getClass());
    Assert.assertEquals(CsrfPreventionFilter.SuffixPredicate.class, ((CsrfPreventionFilter.MimePredicate) item).getPredicate().getClass());
    item = items.next();
    Assert.assertEquals(CsrfPreventionFilter.MimePredicate.class, item.getClass());
    Assert.assertEquals(CsrfPreventionFilter.PrefixPredicate.class, ((CsrfPreventionFilter.MimePredicate) item).getPredicate().getClass());
}

@Test
public void testNoNoncePatternMatchers() {
    String[] urls = { "/images/home.png" };
    Predicate<String> prefix = new CsrfPreventionFilter.PrefixPredicate("/images/");
    Predicate<String> suffix = new CsrfPreventionFilter.SuffixPredicate(".png");
    Predicate<String> regex = new CsrfPreventionFilter.PatternPredicate("^(/images/.*|.*\\.png)$");
    for (String url : urls) {
        Assert.assertTrue("Prefix match fails", prefix.test(url));
        Assert.assertTrue("Suffix match fails", suffix.test(url));
        Assert.assertTrue("Pattern match fails", regex.test(url));
    }
    ArrayList<Predicate<String>> chain = new ArrayList<>();
    chain.add(prefix);
    chain.add(suffix);
    chain.add(regex);
    HttpServletResponse response = new CsrfPreventionFilter.CsrfResponseWrapper(new NonEncodingResponse(), Constants.CSRF_NONCE_SESSION_ATTR_NAME, "TESTNONCE", chain);
    // These URLs should include nonces
    Assert.assertEquals("/foo?" + RESULT_NONCE, response.encodeURL("/foo"));
    Assert.assertEquals("/foo/images?" + RESULT_NONCE, response.encodeURL("/foo/images"));
    Assert.assertEquals("/foo/images/home.jpg?" + RESULT_NONCE, response.encodeURL("/foo/images/home.jpg"));
    // These URLs should not
    Assert.assertEquals("/images/home.png", response.encodeURL("/images/home.png"));
    Assert.assertEquals("/images/home.jpg", response.encodeURL("/images/home.jpg"));
    Assert.assertEquals("/home.png", response.encodeURL("/home.png"));
    Assert.assertEquals("/home.png", response.encodeURL("/home.png"));
}

@Test
public void testNoNonceMimeMatcher() {
    MimeTypeServletContext context = new MimeTypeServletContext();
    Predicate<String> mime = new CsrfPreventionFilter.MimePredicate(context, new CsrfPreventionFilter.PrefixPredicate("image/"));
    context.setMimeType("image/png");
    Assert.assertTrue("MIME match fails", mime.test("/images/home.png"));
    context.setMimeType("text/plain");
    Assert.assertFalse("MIME match succeeds where it should fail", mime.test("/test.txt"));
    Collection<Predicate<String>> chain = Collections.singleton(mime);
    HttpServletResponse response = new CsrfPreventionFilter.CsrfResponseWrapper(new NonEncodingResponse(), Constants.CSRF_NONCE_SESSION_ATTR_NAME, "TESTNONCE", chain);
    // These URLs should include nonces
    Assert.assertEquals("/foo?" + RESULT_NONCE, response.encodeURL("/foo"));
    Assert.assertEquals("/foo/images?" + RESULT_NONCE, response.encodeURL("/foo/images"));
    Assert.assertEquals("/foo/images/home.jpg?" + RESULT_NONCE, response.encodeURL("/foo/images/home.jpg"));
    Assert.assertEquals("/images/home.png?" + RESULT_NONCE, response.encodeURL("/images/home.png"));
    Assert.assertEquals("/images/home.jpg?" + RESULT_NONCE, response.encodeURL("/images/home.jpg"));
    Assert.assertEquals("/home.png?" + RESULT_NONCE, response.encodeURL("/home.png"));
    context.setMimeType("image/png");
    // These URLs should not
    Assert.assertEquals("/images/home.png", response.encodeURL("/images/home.png"));
    Assert.assertEquals("/images/home.jpg", response.encodeURL("/images/home.jpg"));
    Assert.assertEquals("/home.png", response.encodeURL("/home.png"));
    Assert.assertEquals("/foo", response.encodeURL("/foo"));
    Assert.assertEquals("/foo/home.png", response.encodeURL("/foo/home.png"));
    Assert.assertEquals("/foo/images/home.jpg", response.encodeURL("/foo/images/home.jpg"));
}

/*
     * When this test fails, it tends to enter a long running loop but it will eventually finish (after ~70s on a 8-core
     * Windows box).
     */
@Test
public void testLruCacheConcurrency() throws Exception {
    int threadCount = 2;
    long iterationCount = 100000L;
    Assert.assertTrue(threadCount > 1);
    LruCache<String> cache = new LruCache<>(threadCount - 1);
    LruTestThread[] threads = new LruTestThread[threadCount];
    for (int i = 0; i < threadCount; i++) {
        threads[i] = new LruTestThread(cache, iterationCount);
    }
    for (int i = 0; i < threadCount; i++) {
        threads[i].start();
    }
    for (int i = 0; i < threadCount; i++) {
        threads[i].join();
    }
    for (int i = 0; i < threadCount; i++) {
        Assert.assertTrue(threads[i].getResult());
    }
}

@Test
public void testConfiguration() throws Exception {
    Tomcat tomcat = getTomcatInstance();
    Context root = tomcat.addContext("", TEMP_DIR);
    FilterDef filterDef = new FilterDef();
    filterDef.addInitParameter("ExpiresDefault", "access plus 1 month");
    filterDef.addInitParameter("ExpiresByType text/html", "access plus 1 month 15 days 2 hours");
    filterDef.addInitParameter("ExpiresByType image/gif", "modification plus 5 hours 3 minutes");
    filterDef.addInitParameter("ExpiresByType image/jpg", "A10000");
    filterDef.addInitParameter("ExpiresByType video/mpeg", "M20000");
    filterDef.addInitParameter("ExpiresExcludedResponseStatusCodes", "304, 503");
    ExpiresFilter expiresFilter = new ExpiresFilter();
    filterDef.setFilter(expiresFilter);
    filterDef.setFilterClass(ExpiresFilter.class.getName());
    filterDef.setFilterName(ExpiresFilter.class.getName());
    root.addFilterDef(filterDef);
    FilterMap filterMap = new FilterMap();
    filterMap.setFilterName(ExpiresFilter.class.getName());
    filterMap.addURLPatternDecoded("*");
    tomcat.start();
    try {
        // VERIFY EXCLUDED RESPONSE STATUS CODES
        int[] excludedResponseStatusCodes = expiresFilter.getExcludedResponseStatusCodesAsInts();
        Assert.assertEquals(2, excludedResponseStatusCodes.length);
        Assert.assertEquals(304, excludedResponseStatusCodes[0]);
        Assert.assertEquals(503, excludedResponseStatusCodes[1]);
        // VERIFY DEFAULT CONFIGURATION
        ExpiresConfiguration expiresConfigurationDefault = expiresFilter.getDefaultExpiresConfiguration();
        Assert.assertEquals(StartingPoint.ACCESS_TIME, expiresConfigurationDefault.startingPoint());
        Assert.assertEquals(1, expiresConfigurationDefault.durations().size());
        Assert.assertEquals(DurationUnit.MONTH, expiresConfigurationDefault.durations().get(0).unit());
        Assert.assertEquals(1, expiresConfigurationDefault.durations().get(0).amount());
        // VERIFY TEXT/HTML
        ExpiresConfiguration expiresConfigurationTextHtml = expiresFilter.getExpiresConfigurationByContentType().get("text/html");
        Assert.assertEquals(StartingPoint.ACCESS_TIME, expiresConfigurationTextHtml.startingPoint());
        Assert.assertEquals(3, expiresConfigurationTextHtml.durations().size());
        Duration oneMonth = expiresConfigurationTextHtml.durations().get(0);
        Assert.assertEquals(DurationUnit.MONTH, oneMonth.unit());
        Assert.assertEquals(1, oneMonth.amount());
        Duration fifteenDays = expiresConfigurationTextHtml.durations().get(1);
        Assert.assertEquals(DurationUnit.DAY, fifteenDays.unit());
        Assert.assertEquals(15, fifteenDays.amount());
        Duration twoHours = expiresConfigurationTextHtml.durations().get(2);
        Assert.assertEquals(DurationUnit.HOUR, twoHours.unit());
        Assert.assertEquals(2, twoHours.amount());
        // VERIFY IMAGE/GIF
        ExpiresConfiguration expiresConfigurationImageGif = expiresFilter.getExpiresConfigurationByContentType().get("image/gif");
        Assert.assertEquals(StartingPoint.LAST_MODIFICATION_TIME, expiresConfigurationImageGif.startingPoint());
        Assert.assertEquals(2, expiresConfigurationImageGif.durations().size());
        Duration fiveHours = expiresConfigurationImageGif.durations().get(0);
        Assert.assertEquals(DurationUnit.HOUR, fiveHours.unit());
        Assert.assertEquals(5, fiveHours.amount());
        Duration threeMinutes = expiresConfigurationImageGif.durations().get(1);
        Assert.assertEquals(DurationUnit.MINUTE, threeMinutes.unit());
        Assert.assertEquals(3, threeMinutes.amount());
        // VERIFY IMAGE/JPG
        ExpiresConfiguration expiresConfigurationImageJpg = expiresFilter.getExpiresConfigurationByContentType().get("image/jpg");
        Assert.assertEquals(StartingPoint.ACCESS_TIME, expiresConfigurationImageJpg.startingPoint());
        Assert.assertEquals(1, expiresConfigurationImageJpg.durations().size());
        Duration tenThousandSeconds = expiresConfigurationImageJpg.durations().get(0);
        Assert.assertEquals(DurationUnit.SECOND, tenThousandSeconds.unit());
        Assert.assertEquals(10000, tenThousandSeconds.amount());
        // VERIFY VIDEO/MPEG
        ExpiresConfiguration expiresConfiguration = expiresFilter.getExpiresConfigurationByContentType().get("video/mpeg");
        Assert.assertEquals(StartingPoint.LAST_MODIFICATION_TIME, expiresConfiguration.startingPoint());
        Assert.assertEquals(1, expiresConfiguration.durations().size());
        Duration twentyThousandSeconds = expiresConfiguration.durations().get(0);
        Assert.assertEquals(DurationUnit.SECOND, twentyThousandSeconds.unit());
        Assert.assertEquals(20000, twentyThousandSeconds.amount());
    } finally {
        tomcat.stop();
    }
}

