    addDeleteOnTearDown(docBase);
    // app dir is relative to server home
    org.apache.catalina.Context ctx = tomcat.addWebapp(null, "/webdav", docBase.getAbsolutePath());
    Wrapper w = Tomcat.addServlet(ctx, "servlet", createServlet());
    w.addInitParameter("listings", Boolean.toString(listings));
    w.addInitParameter("readonly", Boolean.toString(readonly));
    w.addInitParameter("allowPostAsGet", "true");
    ctx.addServletMappingDecoded("/*", "servlet");
    // Disable class path scanning - it slows the tests down by almost an order of magnitude
    ((StandardJarScanner) ctx.getJarScanner()).setScanClassPath(false);
    tomcat.start();
    OptionsHttpClient client = new OptionsHttpClient();
    client.setPort(getPort());
    // @formatter:off
    client.setRequest(new String[] { "OPTIONS /webdav/" + url + " HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "Connection: close" + CRLF + CRLF });
    // @formatter:on
    client.connect();
    client.processRequest();
    Assert.assertTrue(client.getResponseLine(), client.isResponse200());
    Set<String> allowed = client.getAllowedMethods();
    client.disconnect();
    client.reset();
    // @formatter:off
    client.setRequest(new String[] { method + " /webdav/" + url + " HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "Connection: close" + CRLF + CRLF });
    // @formatter:on
    client.connect();
    client.processRequest();
    String msg = "Listings[" + listings + "], readonly [" + readonly + "], trace[ " + trace + "], url[" + url + "], method[" + method + "]";
    Assert.assertNotNull(client.getResponseLine());
    if (allowed.contains(method)) {
        Assert.assertFalse(msg, client.isResponse405());
    } else {
        Assert.assertTrue(msg, client.isResponse405());
        allowed = client.getAllowedMethods();
        Assert.assertFalse(msg, allowed.contains(method));
    }
}

