    Assert.assertFalse(rootResource.toString().equals(subpathResource.toString()));
    rc = getUrl("http://localhost:" + getPort() + contextPath + "/static/index.html", res, null);
    Assert.assertEquals(HttpServletResponse.SC_NOT_FOUND, rc);
}

