    //
    client.reset();
    // @formatter:off
    client.setRequest(new String[] { "GET /MyApp/missing HTTP/1.1" + CRLF + "Host: localhost" + CRLF + "Connection: close" + CRLF + "If-Modified-Since: " + tomorrow + CRLF + CRLF });
    // @formatter:on
    client.connect();
    client.processRequest();
    Assert.assertTrue(client.isResponse404());
    Assert.assertEquals("It is 404.html", client.getResponseBody());
