        sb.append(CONTENT);
    }
    // @formatter:off
    client.setRequest(new String[] { "PUT /file12.txt HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "Content-Length: " + String.valueOf(sb.length()) + CRLF + "Connection: Close" + CRLF + CRLF + sb.toString() });
    // @formatter:on
    client.connect();
    client.processRequest(true);
    Assert.assertEquals(HttpServletResponse.SC_CREATED, client.getStatusCode());
    // @formatter:off
    client.setRequest(new String[] { "MKCOL /myfolder HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "Connection: Close" + CRLF + CRLF });
    // @formatter:on
    client.connect();
    client.processRequest(true);
    Assert.assertEquals(HttpServletResponse.SC_CREATED, client.getStatusCode());
    // @formatter:off
    client.setRequest(new String[] { "PUT /myfolder/file3.txt HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "Content-Length: 6" + CRLF + "Connection: Close" + CRLF + CRLF + CONTENT });
    // @formatter:on
    client.connect();
    client.processRequest(true);
    Assert.assertEquals(HttpServletResponse.SC_CREATED, client.getStatusCode());
