    Assert.assertTrue(client.getResponseBody().contains("<D:getcontentlength>12<"));
    // Lock /myfolder
    // @formatter:off
    client.setRequest(new String[] { "LOCK /myfolder HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "Content-Length: " + LOCK_BODY.length() + CRLF + "Connection: Close" + CRLF + CRLF + LOCK_BODY });
    // @formatter:on
    client.connect();
    client.processRequest(true);
    Assert.assertEquals(HttpServletResponse.SC_OK, client.getStatusCode());
    Assert.assertTrue(client.getResponseBody().contains("urn:uuid:"));
    String lockToken = null;
    for (String header : client.getResponseHeaders()) {
        if (header.startsWith("Lock-Token: ")) {
            lockToken = header.substring("Lock-Token: ".length());
        }
    }
    Assert.assertNotNull(lockToken);
    // Try to add /myfolder/file4.txt to myfolder without lock token
    // @formatter:off
    client.setRequest(new String[] { "PUT /myfolder/file4.txt HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "Content-Length: 6" + CRLF + "Connection: Close" + CRLF + CRLF + CONTENT });
    // @formatter:on
    client.connect();
    client.processRequest(true);
    Assert.assertEquals(WebdavStatus.SC_LOCKED, client.getStatusCode());
    // Same but provide the lock token
    // @formatter:off
    client.setRequest(new String[] { "PUT /myfolder/file4.txt HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "Content-Length: 6" + CRLF + "If: </myfolder/> (" + lockToken + ")" + CRLF + "Connection: Close" + CRLF + CRLF + CONTENT });
