    // @formatter:off
    client.setRequest(new String[] { "LOCK /myfolder/file5.txt HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "Content-Length: " + LOCK_BODY.length() + CRLF + "Connection: Close" + CRLF + CRLF + LOCK_BODY });
    // @formatter:on
    client.connect();
    client.processRequest(true);
    Assert.assertEquals(WebdavStatus.SC_LOCKED, client.getStatusCode());
    // @formatter:off
    client.setRequest(new String[] { "UNLOCK /myfolder/file5.txt HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "Lock-Token: <my:locktoken>" + CRLF + "Connection: Close" + CRLF + CRLF });
    // @formatter:on
    client.connect();
    client.processRequest(true);
    Assert.assertEquals(HttpServletResponse.SC_CONFLICT, client.getStatusCode());
    Assert.assertTrue(client.getResponseBody().contains("<D:href>/myfolder</D:href>"));
    // Unlock /myfolder
    // @formatter:off
    client.setRequest(new String[] { "UNLOCK /myfolder/file5.txt HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "Lock-Token: " + lockToken + CRLF + "Connection: Close" + CRLF + CRLF });
    // @formatter:on
    client.connect();
    client.processRequest(true);
    Assert.assertEquals(HttpServletResponse.SC_NO_CONTENT, client.getStatusCode());
    // @formatter:off
    client.setRequest(new String[] { "LOCK /myfolder/file5.txt HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "Content-Length: " + LOCK_BODY.length() + CRLF + "Connection: Close" + CRLF + CRLF + LOCK_BODY });
