        if (header.startsWith("Lock-Token: ")) {
            lockTokenFile = header.substring("Lock-Token: ".length());
        }
    }
    Assert.assertNotNull(lockTokenFile);
    // @formatter:off
    client.setRequest(new String[] { "LOCK /myfolder HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "Content-Length: " + LOCK_BODY.length() + CRLF + "Connection: Close" + CRLF + CRLF + LOCK_BODY });
    // @formatter:on
    client.connect();
    client.processRequest(true);
    Assert.assertEquals(WebdavStatus.SC_MULTI_STATUS, client.getStatusCode());
    Assert.assertTrue(client.getResponseBody().contains("/myfolder/file5.txt"));
    Assert.assertTrue(client.getResponseBody().contains("HTTP/1.1 423"));
    // @formatter:off
    client.setRequest(new String[] { "PUT /myfolder/file5.txt HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "Content-Length: 6" + CRLF + "Connection: Close" + CRLF + CRLF + CONTENT });
    // @formatter:on
