    // Same but with lock token and lock null
    // @formatter:off
    client.setRequest(new String[] { "PUT /myfolder/file5.txt HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "Content-Length: 6" + CRLF + "If: (" + lockTokenFile + ")" + CRLF + "Connection: Close" + CRLF + CRLF + CONTENT });
    // @formatter:on
    client.connect();
    client.processRequest(true);
    Assert.assertEquals(HttpServletResponse.SC_NO_CONTENT, client.getStatusCode());
    // Verify that this also removes the lock by doing another PUT without the token
    // @formatter:off
    client.setRequest(new String[] { "DELETE /myfolder/file5.txt HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "If: (" + lockTokenFile + ")" + CRLF + "Connection: Close" + CRLF + CRLF });
