    // @formatter:off
    client.setRequest(new String[] { "LOCK /myfolder HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "Timeout: Second-20" + CRLF + "Content-Length: " + LOCK_BODY.length() + CRLF + "Connection: Close" + CRLF + CRLF + LOCK_BODY });
    // @formatter:on
    client.connect();
    client.processRequest(true);
    Assert.assertEquals(HttpServletResponse.SC_OK, client.getStatusCode());
    Assert.assertTrue(client.getResponseBody().contains("urn:uuid:"));
    lockToken = null;
