        if (header.startsWith("Lock-Token: ")) {
            lockToken = header.substring("Lock-Token: ".length());
        }
    }
    Assert.assertNotNull(lockToken);
    // Copy /myfolder/file5.txt to /myfolder/file6.txt without lock (should not work)
    // @formatter:off
    client.setRequest(new String[] { "COPY /myfolder/file5.txt HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "Destination: http://localhost:" + getPort() + "/myfolder/file6.txt" + CRLF + "Connection: Close" + CRLF + CRLF });
    // @formatter:on
    client.connect();
    client.processRequest(true);
    Assert.assertEquals(WebdavStatus.SC_LOCKED, client.getStatusCode());
    // @formatter:off
    client.setRequest(new String[] { "COPY /myfolder HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "Destination: /myfolder2" + CRLF + "Connection: Close" + CRLF + CRLF });
    // @formatter:on
    client.connect();
    client.processRequest(true);
    Assert.assertEquals(WebdavStatus.SC_CREATED, client.getStatusCode());
    // Delete /myfolder/file4.txt
    // @formatter:off
    client.setRequest(new String[] { "DELETE /myfolder/file4.txt HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "If: (" + lockToken + ")" + CRLF + "Connection: Close" + CRLF + CRLF });
