    // Copy /myfolder/file5.txt to /file7.txt without lock (should work)
    // @formatter:off
    client.setRequest(new String[] { "COPY /myfolder/file5.txt HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "Destination: http://localhost:" + getPort() + "/file7.txt" + CRLF + "Connection: Close" + CRLF + CRLF });
    // @formatter:on
    client.connect();
    client.processRequest(true);
    Assert.assertEquals(HttpServletResponse.SC_CREATED, client.getStatusCode());
    StringBuilder sb2 = new StringBuilder();
    for (int i = 0; i < 3000; i++) {
        sb2.append(CONTENT);
    }
    // @formatter:off
    client.setRequest(new String[] { "PUT /file6.txt HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "Content-Length: " + String.valueOf(sb2.length()) + CRLF + "Connection: Close" + CRLF + CRLF + sb2.toString() });
    // @formatter:on
    client.connect();
    client.processRequest(true);
    Assert.assertEquals(HttpServletResponse.SC_CREATED, client.getStatusCode());
    // Verify that everything created is there
    // @formatter:off
    client.setRequest(new String[] { "PROPFIND / HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "Connection: Close" + CRLF + CRLF });
    // @formatter:on
    client.connect();
    client.processRequest(true);
    Assert.assertEquals(WebdavStatus.SC_MULTI_STATUS, client.getStatusCode());
    Assert.assertFalse(client.getResponseBody().contains("/myfolder/file4.txt"));
    Assert.assertTrue(client.getResponseBody().contains("/file7.txt"));
    Assert.assertTrue(client.getResponseBody().contains("Second-"));
    // SHA-256 hash for "FOOBAR...FOOBAR" (repeats 3000 times)
    Assert.assertTrue(client.getResponseBody().contains("bb94e8d310800b24310036b168aa5a946e27f9572b3d99f956f3a3ed2e7d3045"));
    // SHA-256 hash for "FOOBAR"
    Assert.assertTrue(client.getResponseBody().contains("24c422e681f1c1bd08286c7aaf5d23a5f088dcdb0b219806b3a9e579244f00c5"));
    String timeoutValue = client.getResponseBody().substring(client.getResponseBody().indexOf("Second-"));
    timeoutValue = timeoutValue.substring("Second-".length(), timeoutValue.indexOf('<'));
    Assert.assertTrue(Integer.valueOf(timeoutValue).intValue() <= 20);
    // Unlock /myfolder again
    // @formatter:off
    client.setRequest(new String[] { "UNLOCK /myfolder/ HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "Lock-Token: " + lockToken + CRLF + "Connection: Close" + CRLF + CRLF });
    // @formatter:on
    client.connect();
    client.processRequest(true);
    Assert.assertEquals(HttpServletResponse.SC_NO_CONTENT, client.getStatusCode());
    // Delete /myfolder
    // @formatter:off
    client.setRequest(new String[] { "DELETE /myfolder HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "Connection: Close" + CRLF + CRLF });
    // @formatter:on
    client.connect();
    client.processRequest(true);
    Assert.assertEquals(HttpServletResponse.SC_NO_CONTENT, client.getStatusCode());
    // @formatter:off
    client.setRequest(new String[] { "DELETE /myfolder2 HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "Connection: Close" + CRLF + CRLF });
    // @formatter:on
    client.connect();
    client.processRequest(true);
    Assert.assertEquals(HttpServletResponse.SC_NO_CONTENT, client.getStatusCode());
    // @formatter:off
    client.setRequest(new String[] { "PROPFIND / HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "Connection: Close" + CRLF + CRLF });
    // @formatter:on
    client.connect();
    client.processRequest(true);
    Assert.assertEquals(WebdavStatus.SC_MULTI_STATUS, client.getStatusCode());
    Assert.assertFalse(client.getResponseBody().contains("/myfolder"));
    validateXml(client.getResponseBody());
}

