@Test
public void testConcurrency() throws Exception {
    SaveTask saveTask = new SaveTask();
    Thread saveThread = new Thread(saveTask);
    saveThread.start();
    LoadTask loadTask = new LoadTask();
    Thread loadThread = new Thread(loadTask);
    loadThread.start();
    RemoveTask removeTask = new RemoveTask();
    Thread removeThread = new Thread(removeTask);
    removeThread.start();
    Thread.sleep(TEST_RUN_TIME_MS);
    saveTask.stop();
    loadTask.stop();
    removeTask.stop();
    saveThread.join();
    loadThread.join();
    removeThread.join();
    Assert.assertFalse("Exception during save", saveTask.getFailed());
    Assert.assertFalse("Exception during load", loadTask.getFailed());
    Assert.assertFalse("Exception during remove", removeTask.getFailed());
    System.out.println("Looped over sessions [" + saveTask.getLoopCount() + "] times calling save()");
    System.out.println("Looped over sessions [" + loadTask.getLoopCount() + "] times calling load()");
    System.out.println("Looped over sessions [" + removeTask.getLoopCount() + "] times calling remove()");
}

@Test
public void testMinIdleSwap() throws Exception {
    PersistentManager manager = new PersistentManager();
    manager.setStore(new TesterStore());
    Host host = new TesterHost();
    Context context = new TesterContext();
    context.setParent(host);
    manager.setContext(context);
    manager.setMaxActiveSessions(2);
    manager.setMinIdleSwap(0);
    manager.start();
    // Create the maximum number of sessions
    manager.createSession(null);
    manager.createSession(null);
    // Given the minIdleSwap settings, this should swap one out to get below
    // the limit
    manager.processPersistenceChecks();
    Assert.assertEquals(1, manager.getActiveSessions());
    Assert.assertEquals(2, manager.getActiveSessionsFull());
    manager.createSession(null);
    Assert.assertEquals(2, manager.getActiveSessions());
    Assert.assertEquals(3, manager.getActiveSessionsFull());
