@Test
public void testTokenize() {
    QuotedStringTokenizer tokenizer = new QuotedStringTokenizer(inputText);
    List<String> result = new ArrayList<>();
    int count = tokens.size();
    while (tokenizer.hasMoreTokens()) {
        MatcherAssert.assertThat(Integer.valueOf(tokenizer.countTokens()), CoreMatchers.is(Integer.valueOf(count)));
        result.add(tokenizer.nextToken());
        count--;
    }
    MatcherAssert.assertThat(Integer.valueOf(tokenizer.countTokens()), CoreMatchers.is(Integer.valueOf(0)));
    MatcherAssert.assertThat(tokens, CoreMatchers.is(result));
}

@Test
public void testSslEnv() throws Exception {
    Tomcat tomcat = getTomcatInstance();
    Container root = tomcat.getHost().findChild("");
    root.getPipeline().addValve(new ResolverTestValve());
    // Enable session caching so the SSL Session is available when using OpenSSL
    SSLHostConfig sslHostConfig = tomcat.getConnector().findSslHostConfigs()[0];
    sslHostConfig.setSessionCacheSize(20 * 1024);
    tomcat.start();
    Assume.assumeFalse("LibreSSL does not allow renegotiation", TesterSupport.isOpenSSLVariant(sslImplementationName, OpenSSLStatus.Name.LIBRESSL));
    Assume.assumeFalse("BoringSSL does not allow TLS renegotiation", TesterSupport.isOpenSSLVariant(sslImplementationName, OpenSSLStatus.Name.BORINGSSL));
    ByteChunk res = getUrl("https://localhost:" + getPort() + "/protected");
    // Just look a bit at the result
    System.out.println(res.toString());
    Assert.assertTrue(res.toString().indexOf("OK") > 0);
}

