public void testSpecificUrlPatternLimit() throws Exception {
    Tomcat tomcat = getTomcatInstance();
    StandardContext ctx = (StandardContext) getProgrammaticRootContext();
    ParameterLimitValve parameterLimitValve = new ParameterLimitValve();
    ctx.getPipeline().addValve(parameterLimitValve);
    parameterLimitValve.setUrlPatternLimits("/special/.*=2");
    Tomcat.addServlet(ctx, "snoop", new SnoopServlet());
    ctx.addServletMappingDecoded("/special/endpoint", "snoop");
    tomcat.start();
    int rc = getUrl("http://localhost:" + getPort() + "/special/endpoint?param1=value1&param2=value2&param3=value3", new ByteChunk(), null);
    Assert.assertEquals(400, rc);
    rc = getUrl("http://localhost:" + getPort() + "/special/endpoint?param1=value1&param2=value2", new ByteChunk(), null);
    Assert.assertEquals(200, rc);
    // @formatter:off
    byte[] body = ("POST / HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "Connection: close" + CRLF + "Transfer-Encoding: chunked" + CRLF + "Content-Type: application/x-www-form-urlencoded" + CRLF + CRLF + "param1=value1&param2=value2&param3=value3" + CRLF).getBytes(StandardCharsets.UTF_8);
    // @formatter:on
    rc = postUrl(body, "http://localhost:" + getPort() + "/special/endpoint", new ByteChunk(), null);
    Assert.assertEquals(400, rc);
    // @formatter:off
    body = ("POST / HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "Connection: close" + CRLF + "Transfer-Encoding: chunked" + CRLF + "Content-Type: application/x-www-form-urlencoded" + CRLF + CRLF + "param1=value1&param2=value2" + CRLF).getBytes(StandardCharsets.UTF_8);
    // @formatter:on
    rc = postUrl(body, "http://localhost:" + getPort() + "/special/endpoint", new ByteChunk(), null);
    Assert.assertEquals(200, rc);
    body = ("POST / HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "Connection: close" + CRLF + "Transfer-Encoding: chunked" + CRLF + "Content-Type: application/x-www-form-urlencoded" + CRLF + CRLF + "param1=value1&param2=value2" + CRLF).getBytes(StandardCharsets.UTF_8);
    rc = postUrl(body, "http://localhost:" + getPort() + "/special/endpoint?param3=value3", new ByteChunk(), null);
    Assert.assertEquals(400, rc);
    body = ("POST / HTTP/1.1" + CRLF + "Host: localhost:" + getPort() + CRLF + "Connection: close" + CRLF + "Transfer-Encoding: chunked" + CRLF + "Content-Type: application/x-www-form-urlencoded" + CRLF + CRLF + "param1=value1" + CRLF).getBytes(StandardCharsets.UTF_8);
    rc = postUrl(body, "http://localhost:" + getPort() + "/special/endpoint?param2=value2", new ByteChunk(), null);
    Assert.assertEquals(200, rc);
