    }
    long end = System.nanoTime();
    System.out.println("Regular expression took " + (end - start) + "ns or " + (end - start) / LOOPS + "ns per iteration");
    start = System.nanoTime();
    for (int i = 0; i < LOOPS; i++) {
        checkForBadCharsArray("testfile.jsp ");
    }
    end = System.nanoTime();
    System.out.println("char[] check took " + (end - start) + "ns or " + (end - start) / LOOPS + "ns per iteration");
    start = System.nanoTime();
    for (int i = 0; i < LOOPS; i++) {
        checkForBadCharsAt("testfile.jsp ");
    }
    end = System.nanoTime();
    System.out.println("charAt() check took " + (end - start) + "ns or " + (end - start) / LOOPS + "ns per iteration");
}

