@Test
public void testNotFound() throws Exception {
    Logger.getLogger("org.apache.coyote.http2").setLevel(Level.ALL);
    try {
        http2Connect();
        // Connection and per-stream flow control default to 64k-1 bytes
        // Set up a POST request to a non-existent end-point
        // Generate headers
        byte[] headersFrameHeader = new byte[9];
        ByteBuffer headersPayload = ByteBuffer.allocate(128);
        MimeHeaders headers = new MimeHeaders();
        headers.addValue(":method").setString(Method.POST);
        headers.addValue(":scheme").setString("http");
        headers.addValue(":path").setString("/path-does-not-exist");
        headers.addValue(":authority").setString("localhost:" + getPort());
        headers.addValue("content-length").setLong(65536);
        hpackEncoder.encode(headers, headersPayload);
        headersPayload.flip();
        ByteUtil.setThreeBytes(headersFrameHeader, 0, headersPayload.limit());
        headersFrameHeader[3] = FrameType.HEADERS.getIdByte();
        // Flags. end of headers (0x04)
        headersFrameHeader[4] = 0x04;
        // Stream id
        ByteUtil.set31Bits(headersFrameHeader, 5, 3);
        writeFrame(headersFrameHeader, headersPayload);
        // Generate body
        // Max data payload is 16k
        byte[] dataFrameHeader = new byte[9];
        ByteBuffer dataPayload = ByteBuffer.allocate(16 * 1024);
        while (dataPayload.hasRemaining()) {
            dataPayload.put((byte) 'x');
        }
        dataPayload.flip();
        // Size
        ByteUtil.setThreeBytes(dataFrameHeader, 0, dataPayload.limit());
        ByteUtil.set31Bits(dataFrameHeader, 5, 3);
        // Read the 404 error page
        // headers
        parser.readFrame();
        // body
        parser.readFrame();
        // reset (because the request body was not fully read)
        parser.readFrame();
        // Validate response
        // Response size varies as error page is generated and includes version
        // number
        String trace = output.getTrace();
        int start = trace.indexOf("[content-length]-[") + 18;
        int end = trace.indexOf("]", start);
        String contentLength = trace.substring(start, end);
        // Language will depend on locale
        String language = sm.getLocale().toLanguageTag();
        Assert.assertEquals("3-HeadersStart\n" + "3-Header-[:status]-[404]\n" + "3-Header-[content-type]-[text/html;charset=utf-8]\n" + "3-Header-[content-language]-[" + language + "]\n" + "3-Header-[content-length]-[" + contentLength + "]\n" + "3-Header-[date]-[Wed, 11 Nov 2015 19:18:42 GMT]\n" + "3-HeadersEnd\n" + "3-Body-" + contentLength + "\n" + "3-EndOfStream\n" + "3-RST-[0]\n", output.getTrace());
        output.clearTrace();
        // Write 3*16k=48k of request body
        int count = 0;
        while (count < 3) {
            writeFrame(dataFrameHeader, dataPayload);
            waitForWindowSize(0);
            dataPayload.position(0);
            count++;
        }
        // EOS
        dataFrameHeader[4] = 0x01;
        writeFrame(dataFrameHeader, dataPayload);
        waitForWindowSize(0);
    } finally {
        Logger.getLogger("org.apache.coyote.http2").setLevel(Level.INFO);
    }
}

@Test
public void testEncode() throws Exception {
    MimeHeaders headers = new MimeHeaders();
    headers.setValue("header1").setString("value1");
    headers.setValue(":status").setString("200");
    headers.setValue("header2").setString("value2");
    ByteBuffer output = ByteBuffer.allocate(512);
    HpackEncoder encoder = new HpackEncoder();
    encoder.encode(headers, output);
    output.flip();
    // Size is supposed to be 33 without huffman, or 27 with it
    // TODO: use the HpackHeaderFunction to enable huffman predictably
    Assert.assertEquals(27, output.remaining());
    output.clear();
    encoder.encode(headers, output);
    output.flip();
    // Size is now 3 after using the table
    Assert.assertEquals(3, output.remaining());
}

@Test
public void testDecode() throws Exception {
    MimeHeaders headers = new MimeHeaders();
    headers.setValue("header1").setString("value1");
    headers.setValue(":status").setString("200");
    headers.setValue("header2").setString("value2");
    ByteBuffer output = ByteBuffer.allocate(512);
    HpackEncoder encoder = new HpackEncoder();
    encoder.encode(headers, output);
    output.flip();
    MimeHeaders headers2 = new MimeHeaders();
    HpackDecoder decoder = new HpackDecoder();
    decoder.setHeaderEmitter(new HeadersListener(headers2));
    decoder.decode(output);
    // Redo (table is supposed to be updated)
    output.clear();
    encoder.encode(headers, output);
    output.flip();
    headers2.recycle();
    Assert.assertEquals(3, output.remaining());
    // Check that the decoder is using the table right
    decoder.decode(output);
    Assert.assertEquals("value2", headers2.getHeader("header2"));
}

