@Test
public void testUseCompression() throws Exception {
    CompressionConfig compressionConfig = new CompressionConfig();
    // Skip length and MIME type checks
    compressionConfig.setCompression("force");
    Request request = new Request();
    Response response = new Response();
    for (String header : headers) {
        if (useTE.booleanValue()) {
            request.getMimeHeaders().addValue("TE").setString(header);
        } else {
            request.getMimeHeaders().addValue("accept-encoding").setString(header);
        }
    }
    if (eTag != null) {
        response.getMimeHeaders().addValue("ETag").setString(eTag);
    }
    boolean useCompression = compressionConfig.useCompression(request, response);
    Assert.assertEquals(compress, Boolean.valueOf(useCompression));
    if (useTE.booleanValue()) {
        Assert.assertNull(response.getMimeHeaders().getHeader("Content-Encoding"));
        if (useCompression) {
            Assert.assertEquals("gzip", response.getMimeHeaders().getHeader("Transfer-Encoding"));
        } else {
            Assert.assertNull(response.getMimeHeaders().getHeader("Transfer-Encoding"));
        }
    } else {
        Assert.assertNull(response.getMimeHeaders().getHeader("Transfer-Encoding"));
        if (useCompression) {
            Assert.assertEquals("gzip", response.getMimeHeaders().getHeader("Content-Encoding"));
        } else {
            Assert.assertNull(response.getMimeHeaders().getHeader("Content-Encoding"));
        }
    }
}

@Test
public void testNonBlockingReadWithNoTimeout() {
    // Sends complete request in 3 packets
    ChunkedClient client = new ChunkedClient(true);
    client.doRequest();
    Assert.assertTrue(client.isResponse200());
    Assert.assertTrue(client.isResponseBodyOK());
    Assert.assertNull(EchoListener.t);
}

@Test
public void testNonBlockingReadTimeout() {
    // Sends incomplete request (no end chunk) so read times out
    ChunkedClient client = new ChunkedClient(false);
    client.doRequest();
    Assert.assertFalse(client.isResponse200());
    Assert.assertFalse(client.isResponseBodyOK());
    // Socket will be closed before the error handler runs. Closing the
    // socket triggers the client code's return from the doRequest() method
    // above so we need to wait at this point for the error handler to be
    // triggered.
    int count = 0;
    // Shouldn't need to wait long but allow plenty of time as the CI
    // systems are sometimes slow.
    while (count < 100 && EchoListener.t == null) {
        try {
            Thread.sleep(100);
        } catch (InterruptedException e) {
            // Ignore
        }
        count++;
    }
    Assert.assertNotNull(EchoListener.t);
}

@Test
public void test100ContinueExpectationImmediately() throws IOException {
    // Tests that response.sendAcknowledgement is only called when
    // request.setContinueHandlingResponsePolicy is called.
    request.setExpectation(true);
    // Configure the mock to verify that a network write is made.
    configureMockForOneAcknowledgementWrite(socketWrapper);
    protocol.setContinueResponseTiming(ContinueResponseTiming.IMMEDIATELY.toString());
    response.action(ActionCode.ACK, ContinueResponseTiming.IMMEDIATELY);
    // Verify that acknowledgement is written to network.
    EasyMock.verify(socketWrapper);
    // Configure the mock to verify that no network write is made.
    configureMockForNoAcknowledgementWrite(socketWrapper);
    request.doRead(new DoNothingApplicationBufferHandler());
    // Verify that acknowledgement is not written to network.
    EasyMock.verify(socketWrapper);
}

@Test
public void test100ContinueExpectationOnRequestBodyRead() throws IOException {
    // Tests that response.sendAcknowledgement is only called when
    // request.doRead is called.
    request.setExpectation(true);
    // Configure the mock to verify that no network write is made.
    configureMockForNoAcknowledgementWrite(socketWrapper);
    protocol.setContinueResponseTiming(ContinueResponseTiming.ON_REQUEST_BODY_READ.toString());
    response.action(ActionCode.ACK, ContinueResponseTiming.IMMEDIATELY);
    // Verify that no acknowledgement is written to network.
    EasyMock.verify(socketWrapper);
    // Configure the mock to verify that a network write is made.
    configureMockForOneAcknowledgementWrite(socketWrapper);
    request.doRead(new DoNothingApplicationBufferHandler());
    // Verify that acknowledgement is written to network.
    EasyMock.verify(socketWrapper);
}

@Test
public void testNoExpectationWithOnRequestBodyReadPolicy() throws IOException {
    // When expectation is false, sendAcknowledgement must never be called.
    request.setExpectation(false);
