    testExpression("$", "$");
    testExpression("$$", "$$");
    testExpression("$$$", "$$$");
    testExpression("#$", "#$");
    testExpression("#$#", "#$#");
    testExpression("$#", "$#");
    testExpression("$#$", "$#$");
    testExpression("#{1+1}", "2");
    testExpression("##{1+1}", "#2");
    testExpression("###{1+1}", "##2");
    testExpression("${1+1}", "2");
    testExpression("$${1+1}", "$2");
    testExpression("$$${1+1}", "$$2");
    testExpression("#${1+1}", "#2");
    testExpression("#$#{1+1}", "#$2");
    testExpression("$#{1+1}", "$2");
    testExpression("$#${1+1}", "$#2");
}

