    int rc = getUrl("http://localhost:" + getPort() + "/test/bug6nnnn/bug65377.jsp", bc, null);
    String body = bc.toString();
    String[] lines = body.split("\n");
    for (String line : lines) {
        line = line.trim();
        if (line.startsWith("<p>")) {
            line = line.substring(3, line.length() - 4);
