@Test
public void testCVE_2025_53506() throws Exception {
    enableHttp2(100);
    configureAndStartWebApplication();
    openClientConnection(false, false);
    doHttpUpgrade();
    sendClientPreface();
    validateHttp2InitialResponse(100);
    int streamId = 3;
    Throwable t = null;
    try {
        /*
             * Note: The client will create streams and send requests faster than Tomcat can process them so the
             * concurrent stream count will be well above 100 by the time the client sees the exception. However,
             * Tomcat will only have processed the first 100.
             */
        while (true) {
            sendSimpleGetRequest(streamId);
            streamId += 2;
        }
    } catch (IOException ioe) {
        t = ioe;
    }
    Assert.assertNotNull(t);
}

@Test
public void testClassParserPerformance() throws IOException {
    File libDir = new File(JAR_LOCATION);
    String[] libs = libDir.list();
    Assert.assertNotNull(libs);
    Set<URL> jarURLs = new HashSet<>();
    for (String lib : libs) {
        if (!lib.toLowerCase(Locale.ENGLISH).endsWith(".jar")) {
            continue;
        }
        jarURLs.add(URI.create("jar:" + new File(libDir, lib).toURI().toURL().toExternalForm() + "!/").toURL());
    }
    long duration = 0;
    for (URL jarURL : jarURLs) {
        try (Jar jar = JarFactory.newInstance(jarURL)) {
            jar.nextEntry();
            String jarEntryName = jar.getEntryName();
            while (jarEntryName != null) {
                if (jarEntryName.endsWith(".class")) {
                    InputStream is = jar.getEntryInputStream();
                    long start = System.nanoTime();
                    ClassParser cp = new ClassParser(is);
                    cp.parse();
                    duration += System.nanoTime() - start;
                }
                jar.nextEntry();
                jarEntryName = jar.getEntryName();
            }
        }
    }
    System.out.println("ClassParser performance test took: " + duration + " ns");
}

