public void testInputMalformed01() throws IOException {
    ByteBuffer testInput = ByteBuffer.allocate(1024);
    // TLS handshake
    testInput.put((byte) 22);
    // TLS 1.0
    testInput.put((byte) 3);
    testInput.put((byte) 1);
