    handler.getLatch().await(TesterFirehoseServer.WAIT_TIME_MILLIS, TimeUnit.MILLISECONDS);
    Assert.assertEquals(TesterFirehoseServer.MESSAGE_COUNT, handler.getMessageCount());
}

